#!/usr/bin/env python3
"""Generate a portable Module using existing AM actions and Viewer blocks."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
DEST=(ROOT.parents[1] / 'daily-routine')/'agents/main'
def dump(path,data):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def code(id,body,out):return {'id':id,'type':'code_execution','code':body,'output_key':out}
def tool(id,name,params,out):return {'id':id,'type':'tool_call','tool':name,'params':params,'output_key':out}
def call(id,wf,inp,out):return {'id':id,'type':'workflow_call','workflow_id':wf,'workflow_version':'1','execution':'sync','input':inp,'output_key':out}
def field(name,title,kind='string',options=None):
    x={'name':name,'title':title,'type':kind,'required':True}
    if options:x['options']=[{'value':v,'label':l}for v,l in options]
    return x
def wf(id,title,actions,output,fields=None):
    x={'$schema':'agentmaurice.workflow/v2','schema_version':2,'kind':'workflow','workflow_id':id,'version':'1','title':title,'actions':actions,'output':output}
    if fields:x['forms']=[{'id':'submit','title':title,'fields':fields,'actions_on_submit':[a['id']for a in actions]}]
    dump(DEST/'workflows'/(id+'.json'),x);return x
JEUX=[('usage','Mesures réelles'),('qualification','Données de test')]
BOOL=[('non','Non'),('oui','Oui')]
DIMS=[('execution_minutes','Travail (minutes)'),('relecture_minutes','Relecture (minutes)'),('correction_minutes','Corrections (minutes)'),('supervision_minutes','Supervision (minutes)'),('maintenance_minutes','Maintenance récurrente affectée (minutes)'),('installation_minutes','Mise en place initiale affectée (minutes)')]
def app(id,title,workflow,fields,layout,extra=None,defaults=None):
    props={f['name']:{'type':['number','string']if f['type']=='number'else'string'}for f in fields}
    props.update({k:{'type':'object'}for k in ['result','listing','selected']})
    initial={f['name']:0 if f['type']=='number'else''for f in fields};initial.update({'result':{'message':'Aucune saisie effectuée.'},'listing':{'items':[]},'selected':{'content':''}});initial.update(defaults or{})
    events=[{'event_id':'submit','trigger':'form.submit','workflow':{'workflow_id':workflow,'input':{f['name']:'{{ state.'+f['name']+' }}'for f in fields}},'result_to_state':'result'}]+(extra or[])
    x={'$schema':'agentmaurice.miniapp/v2','schema_version':2,'kind':'miniapp','miniapp_id':id,'version':'1','title':title,'description':'Routine manuelle interne ; aucun envoi ni publication.','ui':{'renderer':'component','component':'daily-routine','configuration':{'layout':layout}},'state_schema':{'type':'object','properties':props},'initial_state':initial,'events':events}
    dump(DEST/'miniapps'/(id+'.json'),x)
def text(value):return {'type':'text','value':value}
def bound(path):return {'state':path}
def build():
    js=(ROOT/'metrics.js').read_text().replace('export ','')
    fields=[field('jeu','Nature des données','select',JEUX),field('session_id','Identifiant de mesure (réutiliser pour corriger)'),field('comparaison_id','Paire de comparaison'),field('date','Date du travail','date'),field('phase','Méthode','select',[('reference','Référence sans assistance AM'),('assiste','Avec assistance AM')]),field('dossier_id','Dossier ou livrable local'),field('categorie','Type de travail comparable'),field('complexite','Complexité','select',[('courte','Courte'),('standard','Standard'),('complexe','Complexe')]),field('critere_qualite','Critère de qualité fixé avant le travail','text'),field('qualite','Qualité relue','select',[('a_revoir','À revoir'),('valide','Validée pour cet objectif interne'),('rejete','Rejetée')]),field('mesure_ref','Référence du relevé de temps'),field('prochaine_etape','Prochaine étape / blocage','text')]+[field(k,v,'number')for k,v in DIMS]+[field('temps_observe','Temps réellement relevés (pas une estimation)','select',BOOL),field('confirmation_manuelle','Confirmer cette saisie ou correction','select',BOOL)]
    wf('daily-time-save','Noter le temps passé',[
      code('validate',js+'\n\n\nreturn validateEntry({{ json . }});','record'),
      tool('save','write_file',{'path':'/company-in-a-box/daily/{{ record.jeu }}/{{ record.session_id }}.json','content':'{{ .record | json }}','overwrite':True},'saved')
    ],{'record':'{{ record }}','message':'Temps enregistré. Le gain nécessite une référence comparable et deux livrables de qualité validée.','external_effect':False},fields)
    validate='const x=({{ json . }}).entry || ({{ json . }}); if(!["usage","qualification"].includes(x.jeu)||typeof x.session_id!=="string"||!/^[a-z0-9][a-z0-9-]{0,63}$/.test(x.session_id)) throw new Error("invalid_time_record_ref"); return {jeu:x.jeu,session_id:x.session_id};'
    wf('daily-time-read','Relire une mesure',[
      code('validate',validate,'request'),tool('read','read_file',{'path':'/company-in-a-box/daily/{{ request.jeu }}/{{ request.session_id }}.json'},'stored'),
      code('decode','const r=JSON.parse(({{ json .stored }}).content);const q={{ json .request }};if(r.session_id!==q.session_id||r.jeu!==q.jeu||r.schema_version!==1)throw new Error("stored_measurement_mismatch");return {record:r,content:JSON.stringify(r,null,2)};','detail')
    ],{'record':'{{ detail.record }}','content':'{{ detail.content }}'})
    report_fields=[field('jeu','Nature des données','select',JEUX),field('date_debut','Début (inclure la période de référence)','date'),field('date_fin','Fin','date')]
    wf('daily-report','Bilan du temps observé',[
      code('validate','const x={{ json . }};function date(v){return typeof v==="string"&&/^\\d{4}-\\d{2}-\\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;}if(!["usage","qualification"].includes(x.jeu)||!date(x.date_debut)||!date(x.date_fin)||x.date_debut>x.date_fin)throw new Error("invalid_report_period");return {jeu:x.jeu,date_debut:x.date_debut,date_fin:x.date_fin};','request'),
      tool('list','list_files',{'path':'/company-in-a-box/daily/{{ request.jeu }}'},'files'),
      code('entries','const files={{ json .files }};const q={{ json .request }};if(!Array.isArray(files))throw new Error("invalid_time_listing");const entries=files.filter(f=>typeof f.path==="string"&&f.path.endsWith(".json")).map(f=>({session_id:f.path.split("/").pop().replace(/\\.json$/,""),jeu:q.jeu}));if(entries.length>100)throw new Error("time_journal_limit_100_exceeded");return entries;','entries'),
      {'id':'read','type':'for_each','items':'{{ entries }}','item_key':'entry','max_items':100,'on_empty':'continue','workflow_id':'daily-time-read','output_key':'records'},
      code('summary',js+'\n\n\nconst all={{ json .records }};const entries={{ json .entries }};if(all===null&&entries.length===0)return summarize([],{{ json .request }});if(!Array.isArray(all))throw new Error("invalid_time_records");return summarize(all.map(x=>x.record),{{ json .request }});','report')
    ],{'items':'{{ report.items }}','pairs':'{{ report.pairs }}','exclusions':'{{ report.exclusions }}','summary':'{{ report.summary }}','message':'{{ report.message }}','manual_only':True,'external_effect':False},report_fields)
    context_fields=[field('dossier_id','Dossier local'),field('proposal_id','Révision mémoire à consulter')]
    wf('daily-context','Préparer mon dossier avec la mémoire',[
      call('dossier','daily-role-read',{'dossier_id':'{{ dossier_id }}'},'local'),call('memory','company-memory-query',{'proposal_id':'{{ proposal_id }}'},'memory'),
      code('context','const r=({{ json .local }}).data.record;const m=({{ json .memory }}).data;const valid=m.status==="validated"&&typeof m.answer==="string"&&m.answer.trim()&&Array.isArray(m.citations)&&m.citations.length>0&&Number.isFinite(Date.parse(m.expires_at))&&Date.parse(m.expires_at)>Date.now();return {dossier:r,content:JSON.stringify(r,null,2),memory_status:m.status,memory_answer:valid?m.answer:"Mémoire non utilisable : une revue est nécessaire.",citations:valid?m.citations:[],proposal_id:m.proposal_id,expires_at:m.expires_at||"",ready:!!valid,message:valid?"Contexte disponible. Préparez le livrable interne, puis relisez-le avant de noter le temps.":"Mémoire non validée ou périmée : ne pas utiliser comme fait. Revenir à la collecte ou à la revue mémoire."};','context')
    ],{'dossier':'{{ context.dossier }}','content':'{{ context.content }}','memory_status':'{{ context.memory_status }}','memory_answer':'{{ context.memory_answer }}','citations':'{{ context.citations }}','proposal_id':'{{ context.proposal_id }}','expires_at':'{{ context.expires_at }}','ready':'{{ context.ready }}','message':'{{ context.message }}','manual_only':True,'external_effect':False},context_fields)
    app('daily-time-console','Journal de temps','daily-time-save',fields,[text('Mesurez le temps humain réel, pauses exclues. Affectez chaque minute à un seul dossier. Même identifiant = correction du relevé, pas ajout.'),text(bound('result.message')),text('Temps humain récurrent (minutes)'),text(bound('result.record.temps_humain_minutes')),text('Mise en place initiale (minutes), hors gain récurrent'),text(bound('result.record.installation_minutes'))],defaults={'jeu':'usage','phase':'reference','complexite':'standard','qualite':'a_revoir','temps_observe':'non','confirmation_manuelle':'non'})
    app('daily-report-console','Briefing et bilan du temps','daily-report',report_fields,[text('Bilan descriptif : les données de test ne prouvent aucun gain réel. Les deux périodes doivent être incluses.'),text(bound('result.message')),{'type':'metric','label':'Gain récurrent (minutes)','value':bound('result.summary.gain_minutes')},{'type':'metric','label':'Mise en place (minutes)','value':bound('result.summary.installation_minutes')},{'type':'metric','label':'Temps humain total (minutes)','value':bound('result.summary.total_temps_humain_minutes')},text('Mesures exclues de la comparaison'),{'type':'table','columns':['comparaison_id','reason'],'rows':bound('result.exclusions')},{'type':'table','columns':['session_id','date','phase','dossier_id','qualite','temps_humain_minutes','prochaine_etape'],'column_labels':{'session_id':'Mesure','date':'Date','phase':'Méthode','dossier_id':'Dossier','qualite':'Qualité','temps_humain_minutes':'Minutes humaines','prochaine_etape':'Prochaine étape'},'rows':bound('result.items'),'on_row_click':'select'},text('Mesure sélectionnée'),text(bound('selected.content'))],[{'event_id':'select','trigger':'table.row_click','workflow':{'workflow_id':'daily-time-read','input':{'session_id':'{{ event.payload.item.session_id }}','jeu':'{{ state.jeu }}'}},'result_to_state':'selected'}],{'jeu':'usage','result':{'items':[],'exclusions':[],'message':'Aucune période consultée.'}})
    app('daily-context-console','Ma routine — dossier et mémoire', 'daily-context',context_fields,[{'type':'steps','items':[{'title':'Choisir un dossier','description':'Veille : source datée. Contenu : brouillon interne. Accompagnement : prochaine aide à préparer.','status':'todo'},{'title':'Consulter la mémoire','description':'Chercher une révision, vérifier sa date et ses citations.','status':'todo'},{'title':'Préparer et relire','description':'Utiliser les écrans du rôle. Un brouillon préparé ne prouve ni publication ni essai réussi.','status':'todo'},{'title':'Noter le temps et le retour','description':'Journal de temps, puis extrait proposé à la mémoire. La revue mémoire reste distincte.','status':'todo'}]},text(bound('result.message')),text('Dossier local'),text(bound('result.content')),text('Mémoire'),text(bound('result.memory_status')),text(bound('result.memory_answer')),text('Révision'),text(bound('result.proposal_id')),text('Sources'),text(bound('result.citations')),text('À revoir avant'),text(bound('result.expires_at'))])
    manifest={'$schema':'agentmaurice.module/v2','schema_version':2,'key':'cib-daily-routine','name':'Routine quotidienne — dossiers, mémoire et temps','version':'0.1.0','provides':{'actions':[{'key':'daily-time-save','workflow_id':'daily-time-save','workflow_version':'1'}],'queries':[{'key':n,'workflow_id':n,'workflow_version':'1'}for n in ['daily-time-read','daily-report','daily-context']],'apps':[{'key':n,'miniapp_id':n,'miniapp_version':'1'}for n in ['daily-time-console','daily-report-console','daily-context-console']]},'requires':{}}
    dump((ROOT.parents[1] / 'daily-routine')/'module.yaml',manifest)
if __name__=='__main__':build()
